// To support errors.Unwrap().
func (e errLoadWbl) Unwrap() error {
	return e.err
}

// isErrLoadOOOWal returns a boolean if the error is errLoadWbl.
func isErrLoadOOOWal(err error) bool {
	_, ok := err.(*errLoadWbl)
	return ok
